use std::fmt::Write;

use qbt_api::{capabilities::MIN_VERSIONS, endpoints::ENDPOINTS};

/// The manifest text for `docs/endpoints.toml`.
pub fn manifest() -> String {
    let mut out = String::from(
        "# Generated by `cargo xtask endpoints`; do not edit. Source of truth: crates/qbt-api/src/endpoints.rs\n\
         # (mirrors docs/api-inventory.md, WebAPI 2.17.0). `min_webapi` comes from WebAPI_Changelog.md.\n",
    );
    for e in ENDPOINTS {
        let min = MIN_VERSIONS
            .iter()
            .find(|(s, a, _)| *s == e.scope && *a == e.action)
            .map(|(_, _, v)| v.to_string());
        let _ = write!(
            out,
            "\n[[endpoint]]\nscope = \"{}\"\naction = \"{}\"\nmethod = \"{}\"\n",
            e.scope,
            e.action,
            if e.post { "POST" } else { "GET" }
        );
        if let Some(v) = min {
            let _ = writeln!(out, "min_webapi = \"{v}\"");
        }
    }
    out
}

pub fn run(check: bool) -> anyhow::Result<()> {
    let path = crate::repo_root().join("docs/endpoints.toml");
    let want = manifest();
    if check {
        let have = std::fs::read_to_string(&path).unwrap_or_default();
        anyhow::ensure!(
            have == want,
            "{} is out of date: run `cargo xtask endpoints`",
            path.display()
        );
        println!(
            "endpoints.toml is up to date ({} endpoints)",
            ENDPOINTS.len()
        );
    } else {
        std::fs::write(&path, want)?;
        println!("wrote {} ({} endpoints)", path.display(), ENDPOINTS.len());
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    #[test]
    fn checked_in_manifest_is_current() {
        let have = std::fs::read_to_string(crate::repo_root().join("docs/endpoints.toml"))
            .unwrap_or_default();
        assert_eq!(
            have,
            super::manifest(),
            "run `cargo xtask endpoints` to regenerate docs/endpoints.toml"
        );
    }

    #[test]
    fn manifest_has_every_endpoint_once() {
        let m = super::manifest();
        assert_eq!(
            m.matches("[[endpoint]]").count(),
            qbt_api::endpoints::ENDPOINTS.len()
        );
        assert_eq!(qbt_api::endpoints::ENDPOINTS.len(), 133);
    }
}
